   */
  def check_concrete_output(outcomeToAuthorization: Factory_Flow.OutcomeFact => B,
                            outcomeToDeterminer: Factory_Flow.OutcomeFact => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val outcomeToAuthorizationValue: Factory_Flow.OutcomeFact = get_outcomeToAuthorization().get
    if(!outcomeToAuthorization(outcomeToAuthorizationValue)) {
      testFailures = testFailures :+ st"'outcomeToAuthorization' did not match expected: value of the outgoing data port is ${outcomeToAuthorizationValue}"
    }
    val outcomeToDeterminerValue: Factory_Flow.OutcomeFact = get_outcomeToDeterminer().get
    if(!outcomeToDeterminer(outcomeToDeterminerValue)) {
      testFailures = testFailures :+ st"'outcomeToDeterminer' did not match expected: value of the outgoing data port is ${outcomeToDeterminerValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_processResult(value : Factory_Flow.ProcessResultObservation): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_processOutcomeCorrelator.operational_api.processResult_Id, Factory_Flow.ProcessResultObservation_Payload(value))
  }

  // setter for in DataPort
