    }
    return value
  }

  // payload getter for out DataPort
  def get_outcomeToAuthorization_payload(): Option[Factory_Flow.OutcomeFact_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_processOutcomeCorrelator.initialization_api.outcomeToAuthorization_Id).asInstanceOf[Option[Factory_Flow.OutcomeFact_Payload]]
  }

  // getter for out DataPort
  def get_outcomeToDeterminer(): Option[Factory_Flow.OutcomeFact] = {
    val value: Option[Factory_Flow.OutcomeFact] = get_outcomeToDeterminer_payload() match {
